body.script:
    const NOTES = [
      { id: 'C',  label: 'C',  sub: 'Dó',  file: 'C' },
      { id: 'C#', label: 'C#', sub: 'Réb', file: 'Db' },
      { id: 'D',  label: 'D',  sub: 'Ré',  file: 'D' },
      { id: 'D#', label: 'D#', sub: 'Mib', file: 'Eb' },
      { id: 'E',  label: 'E',  sub: 'Mi',  file: 'E' },
      { id: 'F',  label: 'F',  sub: 'Fá',  file: 'F' },
      { id: 'F#', label: 'F#', sub: 'Solb',file: 'Gb' },
      { id: 'G',  label: 'G',  sub: 'Sol', file: 'G' },
      { id: 'G#', label: 'G#', sub: 'Láb', file: 'Ab' },
      { id: 'A',  label: 'A',  sub: 'Lá',  file: 'A' },
      { id: 'A#', label: 'A#', sub: 'Sib', file: 'Bb' },
      { id: 'B',  label: 'B',  sub: 'Si',  file: 'B' }
    ];

    const BANKS = [
      { id: 'cloud',            name: 'Cloud',    fullName: 'Pad Cloud',            folders: ['pads/cloud'] },
      { id: 'dark',             name: 'Dark',     fullName: 'Pad Dark',             folders: ['pads/dark'] },
      { id: 'reverse',          name: 'Reverse',  fullName: 'Pad Reverse',          folders: ['pads/reverse'] },
      { id: 'reverse-especial', name: 'Rev. Esp', fullName: 'Pad Reverse Especial', folders: ['pads/reverse-especial', 'pads/reverse%20especial'] },
      { id: 'soft',             name: 'Soft',     fullName: 'Pad Soft (Synth)',     folders: [], synth: true }
    ];

    // Mapeamento dos nomes originais das pastas Muka caso não estejam renomeados
    const ALT_FILENAMES = {
      'C':  ['C.mp3', 'C(Am).mp3', 'c.mp3'],
      'C#': ['Db.mp3', 'C%23.mp3', 'C%23(Db).mp3', 'c%23.mp3'],
      'D':  ['D.mp3', 'D(Bm).mp3', 'd.mp3'],
      'D#': ['Eb.mp3', 'D%23.mp3', 'D%23(Eb).mp3', 'D(Cm).mp3', 'd%23.mp3'],
      'E':  ['E.mp3', 'E(Cm).mp3', 'E(Dbm).mp3', 'e.mp3'],
      'F':  ['F.mp3', 'F(Dm).mp3', 'f.mp3'],
      'F#': ['Gb.mp3', 'F%23.mp3', 'f%23.mp3', 'F%23(Gb).mp3'],
      'G':  ['G.mp3', 'G(E).mp3', 'G(Em).mp3', 'g.mp3'],
      'G#': ['Ab.mp3', 'G%23.mp3', 'G%23(Ab).mp3', 'g%23.mp3'],
      'A':  ['A.mp3', 'A(F).mp3', 'A(Gbm).mp3', 'a.mp3'],
      'A#': ['Bb.mp3', 'A%23.mp3', 'A%23(Bb).mp3', 'a%23.mp3'],
      'B':  ['B.mp3', 'B(Gm).mp3', 'B(Abm).mp3', 'b.mp3']
    };

    const state = {
      activeKey: null,
      locked: false,
      pad1Bank: 'cloud',
      pad2Bank: 'reverse',
      pad1On: true,
      pad2On: true,
      vol1: 0.85,
      vol2: 0.50,
      cutoff: 4500,
      xfade: 2.5,
      bass: 2,
      treble: 0,
      readyBanks: { 'soft': true }
    };

    // IndexedDB para salvar MP3 offline
    let db;
    function initDB() {
      return new Promise((resolve) => {
        const req = indexedDB.open('DualPadStageDB', 1);
        req.onupgradeneeded = (e) => {
          const d = e.target.result;
          if (!d.objectStoreNames.contains('samples')) {
            d.createObjectStore('samples');
          }
        };
        req.onsuccess = (e) => {
          db = e.target.result;
          resolve();
        };
        req.onerror = () => resolve();
      });
    }

    function saveSample(key, blob) {
      return new Promise((resolve) => {
        if (!db) return resolve();
        const tx = db.transaction('samples', 'readwrite');
        tx.objectStore('samples').put(blob, key);
        tx.oncomplete = () => resolve();
        tx.onerror = () => resolve();
      });
    }

    function getSample(key) {
      return new Promise((resolve) => {
        if (!db) return resolve(null);
        const tx = db.transaction('samples', 'readonly');
        const req = tx.objectStore('samples').get(key);
        req.onsuccess = () => resolve(req.result || null);
        req.onerror = () => resolve(null);
      });
    }

    // Web Audio API
    let ctx, filterNode, bassNode, trebleNode, gainP1, gainP2;
    let currentVoices = [];
    const decodedCache = {};

    function ensureAudio() {
      if (!ctx) {
        const AudioCtx = window.AudioContext || window.webkitAudioContext;
        ctx = new AudioCtx();

        bassNode = ctx.createBiquadFilter();
        bassNode.type = 'lowshelf';
        bassNode.frequency.value = 120;
        bassNode.gain.value = state.bass;

        trebleNode = ctx.createBiquadFilter();
        trebleNode.type = 'highshelf';
        trebleNode.frequency.value = 3200;
        trebleNode.gain.value = state.treble;

        filterNode = ctx.createBiquadFilter();
        filterNode.type = 'lowpass';
        filterNode.frequency.value = state.cutoff;
        filterNode.Q.value = 0.7;

        gainP1 = ctx.createGain();
        gainP2 = ctx.createGain();
        updateLayerGains();

        gainP1.connect(bassNode);
        gainP2.connect(bassNode);
        bassNode.connect(trebleNode);
        trebleNode.connect(filterNode);
        filterNode.connect(ctx.destination);
      }
      if (ctx.state === 'suspended') ctx.resume();
    }

    function updateLayerGains() {
      if (!gainP1 || !gainP2) return;
      const now = ctx.currentTime;
      gainP1.gain.setTargetAtTime(state.pad1On ? state.vol1 : 0, now, 0.05);
      gainP2.gain.setTargetAtTime(state.pad2On ? state.vol2 : 0, now, 0.05);
    }

    function noteFreq(noteId) {
      const idx = NOTES.findIndex(n => n.id === noteId);
      return 130.81 * Math.pow(2, idx / 12);
    }

    function createSynthVoice(noteId, destGain, fadeTime) {
      const now = ctx.currentTime;
      const vGain = ctx.createGain();
      vGain.gain.setValueAtTime(0.0001, now);
      vGain.gain.linearRampToValueAtTime(0.35, now + fadeTime);
      vGain.connect(destGain);

      const base = noteFreq(noteId);
      const ratios = [1, 1.5, 2, 2.5];
      const oscs = ratios.map((r, i) => {
        const osc = ctx.createOscillator();
        osc.type = i % 2 === 0 ? 'sawtooth' : 'triangle';
        osc.frequency.value = base * r;
        osc.detune.value = (i - 1.5) * 6;
        const g = ctx.createGain();
        g.gain.value = 0.18 / (i + 1);
        osc.connect(g);
        g.connect(vGain);
        osc.start(now);
        return osc;
      });

      return {
        stop: (release) => {
          const t = ctx.currentTime;
          vGain.gain.cancelScheduledValues(t);
          vGain.gain.setValueAtTime(Math.max(vGain.gain.value, 0.0001), t);
          vGain.gain.linearRampToValueAtTime(0.0001, t + release);
          setTimeout(() => oscs.forEach(o => { try { o.stop(); } catch(e){} }), release * 1000 + 100);
        }
      };
    }

    async function createSampleVoice(bankId, noteId, destGain, fadeTime) {
      const cacheKey = `${bankId}_${noteId}`;
      let audioBuffer = decodedCache[cacheKey];

      if (!audioBuffer) {
        const blob = await getSample(cacheKey);
        if (blob) {
          const arr = await blob.arrayBuffer();
          audioBuffer = await ctx.decodeAudioData(arr);
          decodedCache[cacheKey] = audioBuffer;
        }
      }

      if (!audioBuffer) {
        return createSynthVoice(noteId, destGain, fadeTime);
      }

      const now = ctx.currentTime;
      const vGain = ctx.createGain();
      vGain.gain.setValueAtTime(0.0001, now);
      vGain.gain.linearRampToValueAtTime(1.0, now + fadeTime);
      vGain.connect(destGain);

      const src = ctx.createBufferSource();
      src.buffer = audioBuffer;
      src.loop = true;
      if (audioBuffer.duration > 6) {
        src.loopStart = 1.5;
        src.loopEnd = audioBuffer.duration - 1.5;
      }
      src.connect(vGain);
      src.start(now);

      return {
        stop: (release) => {
          const t = ctx.currentTime;
          vGain.gain.cancelScheduledValues(t);
          vGain.gain.setValueAtTime(Math.max(vGain.gain.value, 0.0001), t);
          vGain.gain.linearRampToValueAtTime(0.0001, t + release);
          setTimeout(() => { try { src.stop(); } catch(e){} }, release * 1000 + 100);
        }
      };
    }

    async function triggerNote(noteId) {
      if (state.locked) return;
      ensureAudio();

      if (state.activeKey === noteId) return;
      state.activeKey = noteId;
      updateUI();

      const oldVoices = [...currentVoices];
      currentVoices = [];
      oldVoices.forEach(v => v.stop(state.xfade));

      const v1 = await createSampleVoice(state.pad1Bank, noteId, gainP1, state.xfade);
      const v2 = await createSampleVoice(state.pad2Bank, noteId, gainP2, state.xfade);
      currentVoices.push(v1, v2);
    }

    function stopAllPads() {
      if (state.locked) return;
      state.activeKey = null;
      updateUI();
      const oldVoices = [...currentVoices];
      currentVoices = [];
      oldVoices.forEach(v => v.stop(state.xfade));
    }

    // Busca inteligente nas pastas do GitHub
    async function fetchNoteBlob(bank, noteObj) {
      const candidates = ALT_FILENAMES[noteObj.id] || [`${noteObj.file}.mp3`];
      for (const folder of bank.folders) {
        for (const fileName of candidates) {
          try {
            const res = await fetch(`${folder}/${fileName}`);
            if (res.ok) {
              return await res.blob();
            }
          } catch (e) {}
        }
      }
      return null;
    }

    async function downloadBank(bankId, btnEl) {
      const bank = BANKS.find(b => b.id === bankId);
      if (!bank || bank.synth) return;

      if (btnEl) {
        btnEl.disabled = true;
        btnEl.textContent = 'Baixando 0/12...';
      }

      let successCount = 0;
      for (let i = 0; i < NOTES.length; i++) {
        const n = NOTES[i];
        if (btnEl) btnEl.textContent = `Baixando ${i + 1}/12...`;
        const blob = await fetchNoteBlob(bank, n);
        if (blob) {
          await saveSample(`${bank.id}_${n.id}`, blob);
          successCount++;
        }
      }

      if (successCount > 0) {
        state.readyBanks[bank.id] = true;
      } else {
        alert(`Não foi possível encontrar os MP3s de ${bank.fullName} na pasta do GitHub.`);
      }
      renderLibrary();
      renderPills();
    }

    async function checkSavedBanks() {
      for (const b of BANKS) {
        if (b.synth) continue;
        const sample = await getSample(`${b.id}_C`);
        if (sample) state.readyBanks[b.id] = true;
      }
    }

    // RENDERIZAÇÃO DE INTERFACE
    function renderNotes() {
      const grid = document.getElementById('notesGrid');
      grid.innerHTML = '';
      NOTES.forEach(n => {
        const btn = document.createElement('button');
        btn.className = 'note-btn' + (state.activeKey === n.id ? ' active' : '');
        btn.innerHTML = `${n.label}${n.sub}`;
        btn.onclick = () => triggerNote(n.id);
        grid.appendChild(btn);
      });
    }

    function renderPills() {
      const p1Container = document.getElementById('pillsP1');
      const p2Container = document.getElementById('pillsP2');
      p1Container.innerHTML = '';
      p2Container.innerHTML = '';

      BANKS.forEach(b => {
        const isReady = !!state.readyBanks[b.id];

        const btn1 = document.createElement('button');
        btn1.className = `pill ${isReady ? 'ready' : ''} ${state.pad1Bank === b.id ? 'selected-p1' : ''}`;
        btn1.textContent = (isReady ? '' : '☁️ ') + b.name;
        btn1.onclick = async () => {
          if (state.locked) return;
          if (!isReady) {
            document.getElementById('modalLib').classList.add('open');
            return;
          }
          state.pad1Bank = b.id;
          document.getElementById('p1StatusText').textContent = `(${b.name})`;
          renderPills();
          if (state.activeKey) {
            const k = state.activeKey;
            state.activeKey = null;
            triggerNote(k);
          }
        };
        p1Container.appendChild(btn1);

        const btn2 = document.createElement('button');
        btn2.className = `pill ${isReady ? 'ready' : ''} ${state.pad2Bank === b.id ? 'selected-p2' : ''}`;
        btn2.textContent = (isReady ? '' : '☁️ ') + b.name;
        btn2.onclick = async () => {
          if (state.locked) return;
          if (!isReady) {
            document.getElementById('modalLib').classList.add('open');
            return;
          }
          state.pad2Bank = b.id;
          document.getElementById('p2StatusText').textContent = `(${b.name})`;
          renderPills();
          if (state.activeKey) {
            const k = state.activeKey;
            state.activeKey = null;
            triggerNote(k);
          }
        };
        p2Container.appendChild(btn2);
      });
    }

    function renderLibrary() {
      const list = document.getElementById('libList');
      list.innerHTML = '';
      BANKS.filter(b => !b.synth).forEach(b => {
        const isReady = !!state.readyBanks[b.id];
        const div = document.createElement('div');
        div.className = `lib-item ${isReady ? 'ready' : ''}`;
        div.innerHTML = `



${b.fullName}

${isReady ? '✅ Salvo na memória offline' : '☁️ Toque para baixar do GitHub'}

        `;
        const btn = document.createElement('button');
        btn.className = `dl-btn ${isReady ? 'done' : ''}`;
        btn.textContent = isReady ? '✅ Pronto' : '⬇️ Baixar';
        btn.onclick = () => downloadBank(b.id, btn);
        div.appendChild(btn);
        list.appendChild(div);
      });
    }

    function updateUI() {
      document.getElementById('currentKeyDisplay').textContent = state.activeKey || '--';
      renderNotes();
    }

    // EVENTOS
    window.addEventListener('DOMContentLoaded', async () => {
      await initDB();
      await checkSavedBanks();
      renderNotes();
      renderPills();
      renderLibrary();

      document.getElementById('btnStop').onclick = stopAllPads;

      document.getElementById('btnLock').onclick = (e) => {
        state.locked = !state.locked;
        const btn = e.currentTarget;
        btn.classList.toggle('active', state.locked);
        btn.textContent = state.locked ? '🔒 Travado' : '🔓 Trava';
      };

      document.getElementById('btnToggleP1').onclick = (e) => {
        if (state.locked) return;
        state.pad1On = !state.pad1On;
        e.currentTarget.classList.toggle('on-p1', state.pad1On);
        e.currentTarget.textContent = state.pad1On ? 'ON' : 'MUTE';
        updateLayerGains();
      };

      document.getElementById('btnToggleP2').onclick = (e) => {
        if (state.locked) return;
        state.pad2On = !state.pad2On;
        e.currentTarget.classList.toggle('on-p2', state.pad2On);
        e.currentTarget.textContent = state.pad2On ? 'ON' : 'MUTE';
        updateLayerGains();
      };

      document.getElementById('volP1').oninput = (e) => {
        state.vol1 = Number(e.target.value) / 100;
        document.getElementById('volP1Val').textContent = `${e.target.value}%`;
        updateLayerGains();
      };

      document.getElementById('volP2').oninput = (e) => {
        state.vol2 = Number(e.target.value) / 100;
        document.getElementById('volP2Val').textContent = `${e.target.value}%`;
        updateLayerGains();
      };

      const cutoffSlider = document.getElementById('cutoffSlider');
      const updateCutoff = (val) => {
        state.cutoff = Number(val);
        cutoffSlider.value = state.cutoff;
        document.getElementById('cutoffVal').textContent =
          state.cutoff >= 1000 ? `${(state.cutoff / 1000).toFixed(1)} kHz` : `${state.cutoff} Hz`;
        if (filterNode && ctx) {
          filterNode.frequency.setTargetAtTime(state.cutoff, ctx.currentTime, 0.04);
        }
      };

      cutoffSlider.oninput = (e) => {
        document.querySelectorAll('.preset-btn').forEach(b => b.classList.remove('active'));
        updateCutoff(e.target.value);
      };

      document.querySelectorAll('.preset-btn').forEach(btn => {
        btn.onclick = () => {
          document.querySelectorAll('.preset-btn').forEach(b => b.classList.remove('active'));
          btn.classList.add('active');
          updateCutoff(btn.dataset.freq);
        };
      });

      // Modais
      document.getElementById('btnOpenLib').onclick = () => document.getElementById('modalLib').classList.add('open');
      document.getElementById('btnCloseLib').onclick = () => document.getElementById('modalLib').classList.remove('open');
      document.getElementById('btnOpenEq').onclick = () => document.getElementById('modalEq').classList.add('open');
      document.getElementById('btnCloseEq').onclick = () => document.getElementById('modalEq').classList.remove('open');

      document.getElementById('btnDownloadAll').onclick = async (e) => {
        const btn = e.currentTarget;
        btn.disabled = true;
        for (const b of BANKS) {
          if (!b.synth && !state.readyBanks[b.id]) {
            btn.textContent = `Baixando ${b.fullName}...`;
            await downloadBank(b.id, null);
          }
        }
        btn.textContent = '✅ Todos os Pads Baixados!';
      };

      // EQ e Crossfade
      document.getElementById('xfadeSlider').oninput = (e) => {
        state.xfade = Number(e.target.value);
        document.getElementById('xfadeVal').textContent = `${state.xfade.toFixed(1)} s`;
      };

      document.getElementById('bassSlider').oninput = (e) => {
        state.bass = Number(e.target.value);
        document.getElementById('bassVal').textContent = `${state.bass > 0 ? '+' : ''}${state.bass} dB`;
        if (bassNode && ctx) bassNode.gain.setTargetAtTime(state.bass, ctx.currentTime, 0.05);
      };

      document.getElementById('trebleSlider').oninput = (e) => {
        state.treble = Number(e.target.value);
        document.getElementById('trebleVal').textContent = `${state.treble > 0 ? '+' : ''}${state.treble} dB`;
        if (trebleNode && ctx) trebleNode.gain.setTargetAtTime(state.treble, ctx.currentTime, 0.05);
      };
    });
